import React, { useEffect, useMemo, useState } from 'react';
import { useParams } from 'react-router-dom';
import { getCategoryProducts } from '../services/api';

export default function CategoryPage() {
  const { id } = useParams();

  const [cat, setCat] = useState(null);
  const [items, setItems] = useState([]);
  const [q, setQ] = useState('');

  // cargar productos de la categoría
  useEffect(() => {
    (async () => {
      const prods = await getCategoryProducts(id);
      setItems(prods || []);
    })();
  }, [id]);

  // datos de la categoría (para título + banner)
  useEffect(() => {
    (async () => {
      try {
        const res = await fetch('/api/categories');
        const all = await res.json();
        const c = (all || []).find((x) => String(x.id) === String(id));
        setCat(c || null);
      } catch {
        setCat(null);
      }
    })();
  }, [id]);

  // -------- filtro local ----------
  const norm = (s) =>
    String(s || '')
      .toLowerCase()
      .normalize('NFD')
      .replace(/\p{Diacritic}/gu, '');

  const filtered = useMemo(() => {
    const t = norm(q).trim();
    if (!t) return items;
    return items.filter((p) => {
      const name = norm(p.name);
      const desc = norm(p.description);
      const seller = norm(p.seller?.name);
      return name.includes(t) || desc.includes(t) || seller.includes(t);
    });
  }, [q, items]);

  const priceFmt = (n) =>
    typeof n === 'number' ? n.toLocaleString('es-AR') : '';

  const banner = cat?.imageBanner || cat?.imageUrl || '';

  return (
    <div className="cp-cat">
      {/* Banner */}
      <section
        className="hero"
        style={banner ? { backgroundImage: `url(${banner})` } : {}}
        aria-label={cat?.name || `Categoría #${id}`}
      >
        <div className="hero-layer">
          {/* Banda amarilla con logo centrado */}
          <div className="brand-badge">
            <img
              src="/logo-conecta-pinamar.svg"
              alt="Conecta Pinamar"
              className="brand-logo"
            />
          </div>
          <h1 className="title">{(cat?.name || 'Categoría').toUpperCase()}</h1>

          {/* Buscador local (filtra sólo los items de la categoría) */}
          <form
            className="search"
            onSubmit={(e) => {
              e.preventDefault(); // enter no hace nada extra; ya filtramos onChange
            }}
          >
            <input
              type="search"
              placeholder="Buscar ofertas, productos, comercios y más"
              value={q}
              onChange={(e) => setQ(e.target.value)}
              aria-label="Buscar en esta categoría"
            />
            <button type="submit" title="Buscar" aria-label="Buscar">
              <svg width="18" height="18" viewBox="0 0 24 24" aria-hidden="true">
                <path
                  d="M21 21l-4.35-4.35m1.35-5.65a7 7 0 11-14 0 7 7 0 0114 0z"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                />
              </svg>
            </button>
          </form>
        </div>
      </section>

      {/* Grilla de productos */}
      <div className="grid">
        {filtered.map((p) => (
          <a key={p.id} className="card" href={`/producto/${p.id}`}>
            <div className="thumb">
              <img src={p.imageUrl} alt={p.name} loading="lazy" />
            </div>
            <div className="meta">
              <div className="name">{p.name || 'producto'}</div>
              <div className="price">
                {typeof p.price !== 'undefined' ? `$ ${priceFmt(p.price)}` : '$'}
              </div>
            </div>
          </a>
        ))}
        {filtered.length === 0 && (
          <div className="empty">
            {q ? <>Sin resultados para “{q}”.</> : 'No hay productos en esta categoría.'}
          </div>
        )}
      </div>

      {/* Estilos embebidos */}
      <style>{`
        .cp-cat{
          --yellow:#F7D34A;
          --ink:#111;
          --card:#fff;
          --border:#e6e6e6;
          --shadow:0 8px 24px rgba(0,0,0,.08);
        }

        .hero{
          position:relative; width:100%;
          min-height:260px;
          background:#ddd center/cover no-repeat;
          display:grid; place-items:center;
          padding:20px 16px 64px;
        }
        .hero::after{
          content:""; position:absolute; inset:0;
          background:linear-gradient(180deg, rgba(0,0,0,.20), rgba(0,0,0,.35));
        }
        .hero-layer{
          position:relative; z-index:1;
          width:100%; max-width:1100px;
          display:flex; flex-direction:column;
          align-items:center; gap:12px;
        }

        /* Banda amarilla + logo centrado */
        .brand-badge{
          background:var(--yellow);
          border-radius:10px;
          padding:6px 10px;
          display:flex; align-items:center; justify-content:center;
          box-shadow:0 8px 18px rgba(0,0,0,.15);
        }
        .brand-logo{ height:22px; display:block; }

        .title{
          margin:0;
          color:#fff;
          text-align:center;
          text-shadow:0 2px 8px rgba(0,0,0,.35);
          font:800 32px/1.05 system-ui,-apple-system,Segoe UI,Roboto,Ubuntu,Cantarell,Noto Sans,sans-serif;
          letter-spacing:.5px;
        }

        /* Buscador (similar look al unificado) */
        .search{
          margin-top:6px; display:flex; align-items:center; gap:0;
          width:100%; max-width:640px;
          background:#fff; border:2px solid var(--yellow);
          border-radius:999px; padding:6px;
          box-shadow:0 4px 18px rgba(0,0,0,.1);
        }
        .search input{
          flex:1; border:0; outline:none;
          font-size:14px; padding:8px 12px; background:transparent;
        }
        .search button{
          display:grid; place-items:center; border:0; outline:none; cursor:pointer;
          background:var(--yellow); color:#000; border-radius:999px; width:38px; height:38px;
          transition:transform .08s ease, box-shadow .15s ease, opacity .15s ease;
        }
        .search button:hover{ transform:translateY(-1px); box-shadow:0 6px 14px rgba(0,0,0,.18); }
        .search button:active{ transform:translateY(0); box-shadow:none; }

        /* Grilla de cards */
        .grid{
          max-width:1100px; margin:24px auto; padding:0 16px 32px;
          display:grid; grid-template-columns:repeat(auto-fill, minmax(180px, 1fr)); gap:18px;
        }
        .card{
          display:flex; flex-direction:column;
          background:var(--card); border:1px solid var(--border);
          border-radius:16px; text-decoration:none; color:var(--ink);
          box-shadow:var(--shadow);
          transition:transform .12s ease, box-shadow .12s ease;
        }
        .card:hover{ transform:translateY(-2px); box-shadow:0 10px 26px rgba(0,0,0,.12); }
        .thumb{ aspect-ratio:1/1; width:100%; overflow:hidden; border-top-left-radius:16px; border-top-right-radius:16px; }
        .thumb img{ width:100%; height:100%; object-fit:cover; display:block; }
        .meta{ padding:10px 12px 12px; }
        .name{ font-weight:800; font-size:18px; line-height:1.1; margin:0 0 6px 0; }
        .price{ font-weight:900; font-size:20px; }
        .empty{ grid-column:1 / -1; text-align:center; color:#666; padding:24px 0; }

        @media (min-width:900px){
          .hero{ min-height:320px; padding:28px 16px 90px; }
          .brand-logo{ height:24px; }
          .title{ font-size:40px; }
          .grid{ gap:22px; }
          .name{ font-size:20px; }
          .price{ font-size:22px; }
        }
      `}</style>
    </div>
  );
}
